// Tracker against Ultralytics. The data in tracker_fixture.h (generated by
// tools/generate/make_tracker_fixture.py) comes from lap.lapjv, KalmanFilterXYAH and the real
// BYTETracker on seeded synthetic scenes. Three layers, each checked on its own: the assignment
// solver (exact), the Kalman filter (to rounding), the tracker (identifiers, classes and detection
// indexes exact, boxes within a tolerance). Exit code 0 when everything matches.
#include <algorithm>
#include <cmath>
#include <cstddef>
#include <cstdlib>
#include <optional>
#include <vector>

#include "byte_tracker.h"
#include "kalman_filter.h"
#include "lap_solver.h"
#include "logger.h"
#include "tracker_fixture.h"

namespace {
constexpr std::size_t solverRowsMax{32};
constexpr std::size_t solverColumnsMax{32};
// The Python filter solves with LAPACK, so the last digits differ.
constexpr double kalmanTolerance{1e-9};
constexpr float boxTolerance{1e-3F}; // pixels
constexpr double sampleLimit{0.8};

bool checkSolver(const Logger& log) {
    LapSolver solver{LapCapacity{solverRowsMax, solverColumnsMax}};
    for (std::size_t index{0}; index < trackerFixture::solverCases.size(); ++index) {
        const trackerFixture::SolverCase& item{trackerFixture::solverCases.at(index)};
        if (!solver.solve(CostMatrix{trackerFixture::solverCosts.data() + item.firstCost, item.rows,
                                     item.columns},
                          item.limit)) {
            log.error("solver case ", index, ": solve failed");
            return false;
        }
        for (std::size_t row{0}; row < item.rows; ++row) {
            if (solver.columnOfRow(row) != trackerFixture::solverRows.at(item.firstRow + row)) {
                log.error("solver case ", index, " (", item.rows, "x", item.columns, ") row ", row,
                          ": got ", solver.columnOfRow(row), ", lap says ",
                          trackerFixture::solverRows.at(item.firstRow + row));
                return false;
            }
        }
        for (std::size_t column{0}; column < item.columns; ++column) {
            if (solver.rowOfColumn(column) !=
                trackerFixture::solverColumns.at(item.firstColumn + column)) {
                log.error("solver case ", index, " column ", column, ": got ",
                          solver.rowOfColumn(column), ", lap says ",
                          trackerFixture::solverColumns.at(item.firstColumn + column));
                return false;
            }
        }
    }
    // Larger than the capacity: refused, nothing assigned.
    const std::vector<float> big(static_cast<std::size_t>(solverRowsMax + 1), 0.5F);
    return !solver.solve(CostMatrix{big.data(), solverRowsMax + 1, 1}, sampleLimit) &&
           solver.columnOfRow(0) == -1;
}

bool close(double got, double want) {
    return std::fabs(got - want) <= kalmanTolerance * std::max(1.0, std::fabs(want));
}

bool checkKalman(const Logger& log) {
    std::size_t step{0};
    for (std::size_t sequence{0}; sequence < trackerFixture::kalmanLengths.size(); ++sequence) {
        KalmanState state;
        for (std::size_t i{0}; i < trackerFixture::kalmanLengths.at(sequence); ++i, ++step) {
            const trackerFixture::KalmanStep& want{trackerFixture::kalmanSteps.at(step)};
            const Measurement measurement{want.measurement};
            if (want.operation == 0) {
                state = kalman::initiate(measurement);
            } else if (want.operation == 1) {
                kalman::predict(state);
            } else {
                kalman::update(state, measurement);
            }
            for (std::size_t k{0}; k < stateSize; ++k) {
                if (!close(state.mean.at(k), want.mean.at(k))) {
                    log.error("kalman sequence ", sequence, " step ", i, " mean[", k,
                              "]: ", state.mean.at(k), " vs ", want.mean.at(k));
                    return false;
                }
            }
            for (std::size_t k{0}; k < state.covariance.size(); ++k) {
                if (!close(state.covariance.at(k), want.covariance.at(k))) {
                    log.error("kalman sequence ", sequence, " step ", i, " covariance[", k,
                              "]: ", state.covariance.at(k), " vs ", want.covariance.at(k));
                    return false;
                }
            }
        }
    }
    return true;
}

bool sameTrack(const TrackedObject& got, const trackerFixture::OutputBox& want) {
    return got.id == want.id && got.classId == want.classId &&
           got.detectionIndex == want.detectionIndex && got.score == want.score &&
           std::fabs(got.left - want.left) <= boxTolerance &&
           std::fabs(got.top - want.top) <= boxTolerance &&
           std::fabs(got.right - want.right) <= boxTolerance &&
           std::fabs(got.bottom - want.bottom) <= boxTolerance;
}

bool checkFrame(std::size_t scenario, std::size_t index, const trackerFixture::Frame& frame,
                ByteTracker& tracker, const Logger& log) {
    std::vector<Detection> detections;
    for (std::size_t k{0}; k < frame.inputCount; ++k) {
        const trackerFixture::InputBox& input{trackerFixture::inputs.at(frame.firstInput + k)};
        detections.push_back(Detection{input.left, input.top, input.right, input.bottom,
                                       input.confidence, input.classId});
    }
    const std::vector<TrackedObject>& tracks{tracker.update(detections)};
    if (tracks.size() != frame.outputCount) {
        log.error("scenario ", scenario, " frame ", index, ": ", tracks.size(),
                  " tracks, Ultralytics has ", frame.outputCount);
        return false;
    }
    for (std::size_t k{0}; k < tracks.size(); ++k) {
        const trackerFixture::OutputBox& want{trackerFixture::outputs.at(frame.firstOutput + k)};
        if (!sameTrack(tracks.at(k), want)) {
            log.error("scenario ", scenario, " frame ", index, " track ", k, ": id ",
                      tracks.at(k).id, " vs ", want.id, ", box ", tracks.at(k).left, " ",
                      tracks.at(k).top, " ", tracks.at(k).right, " ", tracks.at(k).bottom, " vs ",
                      want.left, " ", want.top, " ", want.right, " ", want.bottom);
            return false;
        }
    }
    return true;
}

bool checkTracker(const Logger& log) {
    std::size_t frameIndex{0};
    for (std::size_t scenario{0}; scenario < trackerFixture::scenarioFrames.size(); ++scenario) {
        std::optional<ByteTracker> tracker{ByteTracker::create(ByteTrackerConfig{}, log)};
        if (!tracker) {
            return false;
        }
        for (std::size_t index{0}; index < trackerFixture::scenarioFrames.at(scenario);
             ++index, ++frameIndex) {
            if (!checkFrame(scenario, index, trackerFixture::frames.at(frameIndex), *tracker,
                            log)) {
                return false;
            }
        }
        if (tracker->overflowCount() != 0) {
            log.error("scenario ", scenario, ": capacity overflow");
            return false;
        }
    }
    return true;
}

// A bad configuration is refused, reset() restarts the identifiers at 1.
bool checkLifecycle(const Logger& log) {
    ByteTrackerConfig bad;
    bad.trackBuffer = 0;
    if (ByteTracker::create(bad, log)) {
        log.error("trackBuffer 0 accepted");
        return false;
    }
    std::optional<ByteTracker> tracker{ByteTracker::create(ByteTrackerConfig{}, log)};
    if (!tracker) {
        return false;
    }
    const std::vector<Detection> one{Detection{100.0F, 100.0F, 200.0F, 300.0F, 0.9F, 4}};
    const std::vector<TrackedObject> first{tracker->update(one)};
    tracker->reset();
    const std::vector<TrackedObject> again{tracker->update(one)};
    if (first.size() != 1 || again.size() != 1 || first.front().id != 1 || again.front().id != 1) {
        log.error("reset() did not restart the identifiers");
        return false;
    }
    return true;
}
} // namespace

int main() {
    const Logger log{"TEST_TRACKER", LogLevel::Debug};
    const bool solver{checkSolver(log)};
    const bool filter{checkKalman(log)};
    const bool tracker{checkTracker(log)};
    const bool lifecycle{checkLifecycle(log)};
    if (solver && filter && tracker && lifecycle) {
        log.info("PASS: ", trackerFixture::solverCases.size(), " solver cases, ",
                 trackerFixture::kalmanSteps.size(), " kalman steps, ",
                 trackerFixture::frames.size(), " frames");
        return EXIT_SUCCESS;
    }
    log.error("FAIL: solver=", solver, " kalman=", filter, " tracker=", tracker,
              " lifecycle=", lifecycle);
    return EXIT_FAILURE;
}
